const body = $input.all()[0].json.body || $input.all()[0].json;

const name = String(body.name || '').trim();
const email = String(body.email || '').trim().toLowerCase();
const phone = String(body.phone || '').trim();
const message = String(body.message || '').trim();
const source = String(body.source || 'web_form').trim();

const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const hasValidEmail = emailRegex.test(email);
const hasMessage = message.length > 0;

if (!hasValidEmail || !hasMessage) {
  return [{
    json: {
      isValid: false,
      errorMessage: !hasValidEmail ? 'Valid email address is required.' : 'Inquiry message cannot be empty.',
      rawInput: body
    }
  }];
}

const leadId = 'lead_' + Date.now() + '_' + Math.random().toString(36).substring(2, 8);
const receivedAt = new Date().toISOString();

return [{
  json: {
    isValid: true,
    leadId: leadId,
    name: name || 'Prospective Client',
    email: email,
    phone: phone || 'Not provided',
    message: message,
    source: source,
    receivedAt: receivedAt
  }
}];

const prev = $('Build AI Prompt').first().json;
const aiRaw = $input.all()[0].json.message?.content || $input.all()[0].json.choices?.[0]?.message?.content || '{}';

let parsed = {};
try {
  const clean = String(aiRaw).replace(/```json\s*/i, '').replace(/```\s*/i, '').trim();
  parsed = JSON.parse(clean);
} catch (err) {
  parsed = {
    intent: 'info',
    property_type: null,
    location: null,
    budget: null,
    timeline: null,
    urgency: 'medium',
    lead_score: 50,
    qualification: 'warm',
    missing_information: ['failed to parse AI JSON'],
    next_action: 'escalate_to_human',
    human_required: true,
    human_reason: 'AI output parse error: ' + err.message,
    reply_subject: 'Thank you for your inquiry, ' + prev.name,
    personalized_reply: 'Dear ' + prev.name + ',\n\nThank you for reaching out to us. A senior property specialist is currently reviewing your inquiry and will follow up with you shortly with curated options.\n\nBest regards,\nAl-Harmain Premier Properties'
  };
}

let score = Number(parsed.lead_score);
if (isNaN(score)) score = 50;
if (score > 100) score = 100;
if (score < 0) score = 0;

let qual = 'warm';
if (score >= 80) qual = 'qualified';
else if (score >= 50) qual = 'warm';
else qual = 'nurture';

const isHuman = parsed.human_required === true;
const hReason = parsed.human_reason || (isHuman ? 'Flagged by AI qualification' : '');

const discordAlert = isHuman
  ? `🚨 **HUMAN ESCALATION ALERT**\n• **Name:** ${prev.name}\n• **Email:** ${prev.email}\n• **Phone:** ${prev.phone}\n• **Reason:** ${hReason}\n• **Customer Inquiry:** "${prev.message}"\n• **Required Action:** Immediate senior agent / manager takeover.`
  : `🔥 **NEW QUALIFIED LEAD (Score: ${score}/100)**\n• **Client:** ${prev.name} (${prev.email})\n• **Phone:** ${prev.phone}\n• **Requirement:** ${parsed.property_type || 'Property'} in ${parsed.location || 'Dubai'}\n• **Budget:** ${parsed.budget || 'Not specified'} · **Timeline:** ${parsed.timeline || 'Flexible'}\n• **Customer Inquiry:** "${prev.message}"\n• **Next Action:** ${parsed.next_action || 'Offer Appointment'}`;

return [{
  json: {
    ...prev,
    ...parsed,
    lead_score: score,
    qualification: qual,
    human_required: isHuman,
    human_reason: hReason,
    discordAlert: discordAlert
  }
}];

const item = $('Parse AI Decision').first().json;

return [{
  json: {
    success: true,
    lead_id: item.leadId,
    lead_score: item.lead_score,
    qualification: item.qualification,
    intent: item.intent,
    property_type: item.property_type,
    location: item.location,
    budget: item.budget,
    timeline: item.timeline,
    next_action: item.next_action,
    human_required: item.human_required,
    reply_subject: item.reply_subject,
    personalized_reply: item.personalized_reply,
    processed_at: new Date().toISOString()
  }
}];

